-- SOURCE: supabase/migrations/018_agents_table.sql
-- Agents table to store agency/company info extracted from listings
-- Includes optional contact fields for future enrichment

create table if not exists public.agents (
  id bigserial primary key,
  name text not null unique,
  logo_url text,
  email text,
  whatsapp text,
  phone text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Keep an association from listings -> agents
alter table if exists public.listings
  add column if not exists agent_id bigint references public.agents(id) on delete set null;

-- Indexes
create index if not exists idx_agents_name on public.agents using btree (name);
create index if not exists idx_listings_agent_id on public.listings using btree (agent_id);

-- Triggers to keep updated_at fresh
create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists trg_agents_set_updated_at on public.agents;
create trigger trg_agents_set_updated_at
before update on public.agents
for each row execute function public.set_updated_at();

-- RLS
alter table public.agents enable row level security;

-- Allow read access to everyone (UI needs to show logos)
do $$ begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'agents' and policyname = 'Allow read for all'
  ) then
    create policy "Allow read for all" on public.agents
      for select using (true);
  end if;
end $$;

-- Allow insert/update/delete to service role only
do $$ begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'agents' and policyname = 'Service role write'
  ) then
    create policy "Service role write" on public.agents
      for all
      using (auth.role() = 'service_role')
      with check (auth.role() = 'service_role');
  end if;
end $$;

-- SOURCE: supabase/migrations/020_vibe_check_tables.sql
-- Vibe Check Tables
-- Used for in-call property carousel and feedback tracking

-- ============================================================================
-- Vibe Check Sessions
-- ============================================================================
-- Stores carousel sessions pushed to frontend during calls

CREATE TABLE IF NOT EXISTS vibe_check_sessions (
  id TEXT PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  properties JSONB NOT NULL,  -- Array of PropertyForCarousel
  status TEXT DEFAULT 'active',  -- active, completed, expired
  has_feedback BOOLEAN DEFAULT false,
  last_feedback_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),

  -- Index for user lookup
  CONSTRAINT vibe_check_sessions_user_fk FOREIGN KEY (user_id) REFERENCES auth.users(id)
);

CREATE INDEX IF NOT EXISTS idx_vibe_check_sessions_user_id ON vibe_check_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_vibe_check_sessions_created_at ON vibe_check_sessions(created_at);

-- ============================================================================
-- Vibe Check Feedback
-- ============================================================================
-- Stores user reactions to individual properties in carousels

CREATE TABLE IF NOT EXISTS vibe_check_feedback (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES vibe_check_sessions(id) ON DELETE CASCADE,
  listing_id TEXT NOT NULL,
  reaction TEXT,  -- 'like', 'dislike', 'curious', 'skip'
  comment TEXT,   -- Optional free-text comment
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_vibe_check_feedback_session_id ON vibe_check_feedback(session_id);
CREATE INDEX IF NOT EXISTS idx_vibe_check_feedback_listing_id ON vibe_check_feedback(listing_id);

-- ============================================================================
-- User Property Explanations
-- ============================================================================
-- Cached personalized explanations for properties (user-specific)

CREATE TABLE IF NOT EXISTS user_property_explanations (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  listing_id TEXT NOT NULL,
  explanation TEXT NOT NULL,
  fit_score INTEGER,
  top_matches TEXT[],
  concerns TEXT[],
  created_at TIMESTAMPTZ DEFAULT NOW(),

  -- Unique per user-listing pair
  UNIQUE(user_id, listing_id)
);

CREATE INDEX IF NOT EXISTS idx_user_property_explanations_user_id ON user_property_explanations(user_id);
CREATE INDEX IF NOT EXISTS idx_user_property_explanations_listing_id ON user_property_explanations(listing_id);

-- ============================================================================
-- RLS Policies
-- ============================================================================

ALTER TABLE vibe_check_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE vibe_check_feedback ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_property_explanations ENABLE ROW LEVEL SECURITY;

-- Sessions: Users can see their own sessions
CREATE POLICY "Users can view own vibe check sessions" ON vibe_check_sessions
  FOR SELECT USING (auth.uid() = user_id);

-- Service role can insert sessions
CREATE POLICY "Service can insert vibe check sessions" ON vibe_check_sessions
  FOR INSERT WITH CHECK (true);

-- Service role can update sessions
CREATE POLICY "Service can update vibe check sessions" ON vibe_check_sessions
  FOR UPDATE USING (true);

-- Feedback: Users can view and insert their own feedback
CREATE POLICY "Users can view own vibe check feedback" ON vibe_check_feedback
  FOR SELECT USING (
    session_id IN (
      SELECT id FROM vibe_check_sessions WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Service can insert vibe check feedback" ON vibe_check_feedback
  FOR INSERT WITH CHECK (true);

-- Explanations: Users can view their own
CREATE POLICY "Users can view own property explanations" ON user_property_explanations
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Service can insert property explanations" ON user_property_explanations
  FOR INSERT WITH CHECK (true);

CREATE POLICY "Service can update property explanations" ON user_property_explanations
  FOR UPDATE USING (true);

-- ============================================================================
-- Enable Realtime
-- ============================================================================

DO $realtime$ BEGIN IF EXISTS(SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.vibe_check_sessions; END IF; END; $realtime$;

COMMENT ON TABLE vibe_check_sessions IS 'Carousel sessions for in-call property showing';
COMMENT ON TABLE vibe_check_feedback IS 'User reactions to properties shown in carousels';
COMMENT ON TABLE user_property_explanations IS 'Cached personalized property explanations per user';

-- SOURCE: supabase/migrations/021_daily_recommendations.sql
-- Daily Recommendations & Notifications Tables
-- For P0 Phase 6: Proactive daily recommendations

-- ============================================================================
-- Daily Recommendations
-- ============================================================================
-- Stores recommendations generated by cron job

CREATE TABLE IF NOT EXISTS daily_recommendations (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  run_id TEXT NOT NULL,  -- Identifies the cron run
  listing_id TEXT NOT NULL,
  rank INTEGER NOT NULL,  -- Position in recommendations (1 = best)
  fit_score INTEGER NOT NULL,
  top_matches TEXT[],
  concerns TEXT[],
  explanation TEXT,

  -- User interaction
  viewed_at TIMESTAMPTZ,
  reaction TEXT,  -- 'like', 'dislike', 'save', 'skip'

  created_at TIMESTAMPTZ DEFAULT NOW(),

  -- Index for efficient lookup
  UNIQUE(user_id, run_id, listing_id)
);

CREATE INDEX IF NOT EXISTS idx_daily_recommendations_user_id ON daily_recommendations(user_id);
CREATE INDEX IF NOT EXISTS idx_daily_recommendations_run_id ON daily_recommendations(run_id);
CREATE INDEX IF NOT EXISTS idx_daily_recommendations_created_at ON daily_recommendations(created_at);

-- ============================================================================
-- User Preferences (if not exists)
-- ============================================================================

CREATE TABLE IF NOT EXISTS user_preferences (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,

  -- Notification preferences
  notification_email BOOLEAN DEFAULT true,
  notification_push BOOLEAN DEFAULT false,
  notification_frequency TEXT DEFAULT 'daily',  -- 'realtime', 'daily', 'weekly', 'never'

  -- Recommendation preferences
  recommendation_count INTEGER DEFAULT 10,  -- Max recs per day
  min_fit_score INTEGER DEFAULT 50,  -- Min score to notify

  -- Last notification sent
  last_email_at TIMESTAMPTZ,
  last_push_at TIMESTAMPTZ,

  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ============================================================================
-- Notification Queue
-- ============================================================================
-- Queue for async notification delivery

CREATE TABLE IF NOT EXISTS notification_queue (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  type TEXT NOT NULL,  -- 'daily_recommendation', 'new_match', 'price_drop', etc.
  channel TEXT NOT NULL,  -- 'email', 'push', 'sms'
  payload JSONB NOT NULL,

  -- Processing
  status TEXT DEFAULT 'pending',  -- 'pending', 'processing', 'sent', 'failed'
  attempts INTEGER DEFAULT 0,
  last_attempt_at TIMESTAMPTZ,
  sent_at TIMESTAMPTZ,
  error TEXT,

  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_notification_queue_status ON notification_queue(status);
CREATE INDEX IF NOT EXISTS idx_notification_queue_user_id ON notification_queue(user_id);
CREATE INDEX IF NOT EXISTS idx_notification_queue_created_at ON notification_queue(created_at);

-- ============================================================================
-- RLS Policies
-- ============================================================================

ALTER TABLE daily_recommendations ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE notification_queue ENABLE ROW LEVEL SECURITY;

-- Daily recommendations: Users see their own
CREATE POLICY "Users can view own daily recommendations" ON daily_recommendations
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can update own daily recommendations" ON daily_recommendations
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Service can insert daily recommendations" ON daily_recommendations
  FOR INSERT WITH CHECK (true);

-- User preferences: Users manage their own
CREATE POLICY "Users can view own preferences" ON user_preferences
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own preferences" ON user_preferences
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own preferences" ON user_preferences
  FOR UPDATE USING (auth.uid() = user_id);

-- Notification queue: Service only
CREATE POLICY "Service can manage notification queue" ON notification_queue
  FOR ALL USING (true);

-- ============================================================================
-- Functions
-- ============================================================================

-- Function to mark recommendation as viewed
CREATE OR REPLACE FUNCTION mark_recommendation_viewed(rec_id UUID)
RETURNS void AS $$
BEGIN
  UPDATE daily_recommendations
  SET viewed_at = NOW()
  WHERE id = rec_id AND user_id = auth.uid();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to react to recommendation
CREATE OR REPLACE FUNCTION react_to_recommendation(rec_id UUID, reaction_type TEXT)
RETURNS void AS $$
BEGIN
  UPDATE daily_recommendations
  SET reaction = reaction_type,
      viewed_at = COALESCE(viewed_at, NOW())
  WHERE id = rec_id AND user_id = auth.uid();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get latest recommendations for user
CREATE OR REPLACE FUNCTION get_latest_recommendations(user_uuid UUID, limit_count INTEGER DEFAULT 10)
RETURNS SETOF daily_recommendations AS $$
BEGIN
  RETURN QUERY
  SELECT *
  FROM daily_recommendations
  WHERE user_id = user_uuid
  ORDER BY created_at DESC, rank ASC
  LIMIT limit_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================================
-- Comments
-- ============================================================================

COMMENT ON TABLE daily_recommendations IS 'Daily property recommendations generated by cron job';
COMMENT ON TABLE user_preferences IS 'User notification and recommendation preferences';
COMMENT ON TABLE notification_queue IS 'Queue for async notification delivery';

