-- SOURCE: supabase/migrations/065_viewings.sql
-- Migration: 065_viewings.sql
-- Purpose: Create viewings table for property viewing management and notes
-- Part of Phase 0: Foundation

-- Viewings table
-- Tracks user interest in properties and viewing appointments
CREATE TABLE IF NOT EXISTS viewings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Who is viewing
  user_id UUID,  -- NULL if from pro_client
  pro_client_id UUID REFERENCES pro_clients(id),

  -- What property
  listing_id TEXT NOT NULL,  -- References listings table or DynamoDB ID

  -- Status tracking
  status TEXT DEFAULT 'interested' CHECK (status IN (
    'interested',      -- User clicked "Quiero verlo"
    'contacted',       -- User contacted agent
    'scheduled',       -- Viewing scheduled
    'completed',       -- Viewing done
    'cancelled'        -- Cancelled
  )),

  -- Agent contact info (captured at interest time)
  agent_phone TEXT,
  agent_whatsapp_url TEXT,

  -- Scheduling
  scheduled_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,

  -- Notes from user during/after viewing
  notes JSONB DEFAULT '[]'::JSONB,

  -- Overall impression (filled after viewing)
  impression TEXT CHECK (impression IN ('positive', 'neutral', 'negative')),
  impression_notes TEXT,

  -- Would they recommend? (for future matching)
  would_recommend BOOLEAN,

  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),

  -- Ensure either user_id or pro_client_id is set
  CONSTRAINT viewing_owner_check CHECK (
    (user_id IS NOT NULL AND pro_client_id IS NULL) OR
    (user_id IS NULL AND pro_client_id IS NOT NULL)
  )
);

-- Viewing notes structure (JSONB array)
-- Each note: { timestamp, category, content, photo_urls? }
-- Categories: general, positive, concern, question, must_verify

-- Indexes
CREATE INDEX IF NOT EXISTS idx_viewings_user_id ON viewings(user_id);
CREATE INDEX IF NOT EXISTS idx_viewings_pro_client_id ON viewings(pro_client_id);
CREATE INDEX IF NOT EXISTS idx_viewings_listing_id ON viewings(listing_id);
CREATE INDEX IF NOT EXISTS idx_viewings_status ON viewings(status);
CREATE INDEX IF NOT EXISTS idx_viewings_created_at ON viewings(created_at DESC);

-- Enable RLS
ALTER TABLE viewings ENABLE ROW LEVEL SECURITY;

-- RLS Policies
-- Users can manage their own viewings
CREATE POLICY "Users can manage own viewings"
  ON viewings
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Pros can see viewings for their clients
CREATE POLICY "Pros can see client viewings"
  ON viewings
  FOR SELECT
  USING (
    pro_client_id IN (
      SELECT id FROM pro_clients WHERE pro_user_id = auth.uid()
    )
  );

-- Pros can update client viewing notes (read-only for status)
CREATE POLICY "Pros can read client viewing notes"
  ON viewings
  FOR UPDATE
  USING (
    pro_client_id IN (
      SELECT id FROM pro_clients WHERE pro_user_id = auth.uid()
    )
  );

-- Update trigger
CREATE OR REPLACE FUNCTION update_viewings_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_viewings_updated_at
  BEFORE UPDATE ON viewings
  FOR EACH ROW
  EXECUTE FUNCTION update_viewings_updated_at();

-- Function to add a note to a viewing
CREATE OR REPLACE FUNCTION add_viewing_note(
  p_viewing_id UUID,
  p_category TEXT,
  p_content TEXT,
  p_photo_urls TEXT[] DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
  v_note JSONB;
  v_result JSONB;
BEGIN
  v_note := jsonb_build_object(
    'id', gen_random_uuid(),
    'timestamp', NOW(),
    'category', p_category,
    'content', p_content,
    'photo_urls', p_photo_urls
  );

  UPDATE viewings
  SET notes = notes || v_note
  WHERE id = p_viewing_id
  RETURNING notes INTO v_result;

  RETURN v_note;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON TABLE viewings IS 'Property viewing tracking and notes for users and pro clients';
COMMENT ON COLUMN viewings.notes IS 'JSONB array of notes: [{id, timestamp, category, content, photo_urls}]';

-- SOURCE: supabase/migrations/066_subscriptions.sql
-- Migration: 066_subscriptions.sql
-- Purpose: Create subscriptions table for Stripe billing integration
-- Part of Phase 0: Foundation

-- Subscriptions table
-- Tracks user subscription status from Stripe
CREATE TABLE IF NOT EXISTS subscriptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

  -- User reference
  user_id UUID NOT NULL UNIQUE,  -- References auth.users

  -- Stripe references
  stripe_customer_id TEXT UNIQUE,
  stripe_subscription_id TEXT UNIQUE,

  -- Plan info
  plan_id TEXT NOT NULL DEFAULT 'free' CHECK (plan_id IN (
    'free',           -- Free tier (limited alerts)
    'personal',       -- Personal subscription (unlimited alerts)
    'pro_solo',       -- Pro solo (1 seat)
    'pro_team',       -- Pro team (multiple seats)
    'enterprise'      -- Enterprise (custom)
  )),

  -- Status (from Stripe)
  status TEXT DEFAULT 'active' CHECK (status IN (
    'active',
    'trialing',
    'past_due',
    'canceled',
    'unpaid',
    'incomplete',
    'paused'
  )),

  -- Billing dates
  current_period_start TIMESTAMPTZ,
  current_period_end TIMESTAMPTZ,
  cancel_at_period_end BOOLEAN DEFAULT FALSE,
  canceled_at TIMESTAMPTZ,

  -- Trial info
  trial_start TIMESTAMPTZ,
  trial_end TIMESTAMPTZ,

  -- Usage limits
  alert_count_this_period INTEGER DEFAULT 0,
  client_count INTEGER DEFAULT 0,  -- For pro plans

  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_subscriptions_user_id ON subscriptions(user_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_stripe_customer ON subscriptions(stripe_customer_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_stripe_subscription ON subscriptions(stripe_subscription_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_plan_id ON subscriptions(plan_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_status ON subscriptions(status);

-- Enable RLS
ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
-- Users can view their own subscription
CREATE POLICY "Users can view own subscription"
  ON subscriptions
  FOR SELECT
  USING (user_id = auth.uid());

-- Only service role can insert/update (from webhooks)
-- No policy needed for INSERT/UPDATE - handled by service role key

-- Update trigger
CREATE OR REPLACE FUNCTION update_subscriptions_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_subscriptions_updated_at
  BEFORE UPDATE ON subscriptions
  FOR EACH ROW
  EXECUTE FUNCTION update_subscriptions_updated_at();

-- Function to check if user has active subscription
CREATE OR REPLACE FUNCTION has_active_subscription(p_user_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM subscriptions
    WHERE user_id = p_user_id
    AND status IN ('active', 'trialing')
    AND (current_period_end IS NULL OR current_period_end > NOW())
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get user's plan features
CREATE OR REPLACE FUNCTION get_plan_features(p_user_id UUID)
RETURNS JSONB AS $$
DECLARE
  v_plan TEXT;
  v_features JSONB;
BEGIN
  SELECT plan_id INTO v_plan
  FROM subscriptions
  WHERE user_id = p_user_id
  AND status IN ('active', 'trialing');

  IF v_plan IS NULL THEN
    v_plan := 'free';
  END IF;

  CASE v_plan
    WHEN 'free' THEN
      v_features := '{
        "alerts_per_month": 5,
        "saved_searches": 1,
        "whatsapp_alerts": false,
        "viewing_notes": true,
        "shortlist_limit": 10,
        "pro_features": false
      }'::JSONB;
    WHEN 'personal' THEN
      v_features := '{
        "alerts_per_month": -1,
        "saved_searches": 5,
        "whatsapp_alerts": true,
        "viewing_notes": true,
        "shortlist_limit": -1,
        "pro_features": false
      }'::JSONB;
    WHEN 'pro_solo' THEN
      v_features := '{
        "alerts_per_month": -1,
        "saved_searches": -1,
        "whatsapp_alerts": true,
        "viewing_notes": true,
        "shortlist_limit": -1,
        "pro_features": true,
        "client_limit": 20,
        "team_members": 1
      }'::JSONB;
    WHEN 'pro_team' THEN
      v_features := '{
        "alerts_per_month": -1,
        "saved_searches": -1,
        "whatsapp_alerts": true,
        "viewing_notes": true,
        "shortlist_limit": -1,
        "pro_features": true,
        "client_limit": -1,
        "team_members": 5
      }'::JSONB;
    ELSE
      v_features := '{
        "alerts_per_month": -1,
        "saved_searches": -1,
        "whatsapp_alerts": true,
        "viewing_notes": true,
        "shortlist_limit": -1,
        "pro_features": true,
        "client_limit": -1,
        "team_members": -1
      }'::JSONB;
  END CASE;

  RETURN v_features;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create free subscription for new users (trigger)
CREATE OR REPLACE FUNCTION create_free_subscription()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO subscriptions (user_id, plan_id, status)
  VALUES (NEW.id, 'free', 'active')
  ON CONFLICT (user_id) DO NOTHING;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Note: This trigger should be created on auth.users but that requires
-- a separate migration or manual setup in Supabase dashboard
