DO $$ BEGIN
  CREATE POLICY "Pros can create link requests"
    ON pro_link_requests FOR INSERT
    WITH CHECK (pro_user_id = auth.uid());
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

